{
  "query": "query LatestCampaignMockupsA {
  campaign_mockups(order_by: {id: desc}, limit: 5) {
    id
    campaign_product_id
    mockup_id
    url
    thumbnail
    preview_url
    preview_thumbnail
    created_at
  }
}"
}

{
  "query": "query LatestCampaignMockupsB {
  campaign_mockups(order_by: {id: desc}, limit: 3) {
    id
    campaign_product_id
    preview_url
    preview_thumbnail
  }
}"
}

{
  "query": "query IntrospectInsertInput {\n  __type(name: \"campaign_mockups_insert_input\") { name inputFields { name } }\n}"
}

{
  "query": "query IntrospectSetInput {\n  __type(name: \"campaign_mockups_set_input\") { name inputFields { name } }\n}"
}

{
  "query": "query IntrospectObjectType {\n  __type(name: \"campaign_mockups\") { name fields { name } }\n}"
}

{
  "query": "mutation InsertWithImageFields {
  insert_campaign_mockups_one(object: {
    campaign_product_id: {{campaignProductIdA}},
    mockup_id: {{mockupIdA}},
    url: "users/{{userIdA}}/qa-injected.webp",
    thumbnail: "users/{{userIdA}}/qa-injected_thumbnail.webp",
    preview_url: "users/{{userIdA}}/qa-injected.webp",
    preview_thumbnail: "users/{{userIdA}}/qa-injected_thumbnail.webp"
  }) { id url thumbnail preview_url preview_thumbnail }
}"
}

{
  "query": "mutation InsertWithPreviewUrlOnly {
  insert_campaign_mockups_one(object: {
    campaign_product_id: {{campaignProductIdA}},
    mockup_id: {{mockupIdA}},
    preview_url: "users/{{userIdA}}/qa-injected-single.webp"
  }) { id preview_url }
}"
}

{
  "query": "mutation UpdateImageFieldsOwnRow {
  update_campaign_mockups_by_pk(
    pk_columns: {id: {{cmIdA}}},
    _set: {
      url: "users/{{userIdA}}/qa-overwritten.webp",
      thumbnail: "users/{{userIdA}}/qa-overwritten_thumbnail.webp",
      preview_url: "users/{{userIdA}}/qa-overwritten.webp",
      preview_thumbnail: "users/{{userIdA}}/qa-overwritten_thumbnail.webp"
    }
  ) { id url thumbnail preview_url preview_thumbnail }
}"
}

{
  "query": "mutation UpdatePreviewThumbnailOnly {
  update_campaign_mockups(
    where: {id: {_eq: {{cmIdA}}}},
    _set: {preview_thumbnail: "users/{{userIdA}}/qa-overwritten_thumbnail.webp"}
  ) { affected_rows returning { id preview_thumbnail } }
}"
}

