  }
}"
}

{
  "query": "query OldRowsStillHaveImages {
  campaign_mockups(order_by: {id: asc}, limit: 20) {
    id
    url
    thumbnail
    preview_url
    preview_thumbnail
    created_at
  }
}"
}

{
  "query": "query CampaignListingWithMockups {
  campaigns(order_by: {id: desc}, limit: 5) {
    id
    name
    campaign_products {
      id
      campaign_mockups(order_by: {position: asc}) {
        id
        position
        master
        url
        thumbnail
        preview_url
        preview_thumbnail
      }
    }
  }
}"
}

{
  "query": "query PrintFileSourceFields {
  campaign_mockups(where: {id: {_eq: {{cmIdA}}}}) {
    id
    master
    layers
    width
    height
    url
    preview_url
    campaign_mockup_printareas { id }
  }
}"
}
